-- k-ramen(https://github.com/raota-team/k-ramen, data/*.toml, 2026-09-25 확인분)으로 v2 매장 정보를 보강한다.
-- 매장은 네이버 플레이스 ID로 찾고, 삭제된 매장은 건너뛴다.
--
-- 1. 영업시간: k-ramen에 영업시간이 있는 매장은 요일별 시간을 k-ramen 것으로 통째로 바꾸고 확인 시각을 넣는다.
--    V29는 v1의 시간 한 벌을 7일에 복사해 요일별 시간·휴무일이 틀린 매장이 많다. 확인 시각이 있어야 앱에 영업 중 여부가 나간다.
--    k-ramen에 없는 요일은 행을 만들지 않는다(관리자 입력과 같다). 마감 24:00은 다음날 00:00으로 넣는다.
--    k-ramen에 영업시간이 없는 매장은 기존 시간과 확인 시각을 그대로 둔다.
--    영업시간을 바꾼 매장은 휴무 안내도 k-ramen 휴무 메모로 바꾼다(없으면 비운다). v1 안내가 새 시간과 어긋나는 매장이 있다.
-- 2. 영업 상태: k-ramen이 폐업으로 표시한 매장은 CLOSED, 나머지 중 아직 UNKNOWN인 매장은 OPERATIONAL로 바꾼다.
--    관리자가 정한 OPERATIONAL·TEMPORARILY_CLOSED는 덮어쓰지 않는다.
--    폐업 매장은 목록·지도·검색에 계속 나오므로 비공개로 돌린다(2026-10-22 기준 11곳 모두 기록·북마크 0건).
-- 3. 라멘 종류: 비어 있는 매장만 앱의 종류 이름으로 바꿔 채운다. 앱에 없는 종류(토리파이탄·지로 등)는 '기타'로 넣는다.
-- 4. 가격: 최저·최고 가격이 모두 비어 있는 매장만 대표 메뉴 가격의 최저·최고로 채운다.
-- 확인 날짜는 한국 날짜이므로 그날 00:00(KST)을 UTC로 바꿔 넣는다.
CREATE TEMPORARY TABLE tmp_kramen_shop (
    naver_place_id VARCHAR(100) NOT NULL PRIMARY KEY,
    is_closed BOOLEAN NOT NULL,
    has_hours BOOLEAN NOT NULL,
    ramen_types JSON NOT NULL,
    price_min INT NULL,
    price_max INT NULL,
    closed_note VARCHAR(50) NULL
);

CREATE TEMPORARY TABLE tmp_kramen_hour (
    naver_place_id VARCHAR(100) NOT NULL,
    day_of_week TINYINT NOT NULL,
    opens_at TIME NULL,
    closes_at TIME NULL,
    break_start TIME NULL,
    break_end TIME NULL,
    is_closed BOOLEAN NOT NULL,
    PRIMARY KEY (naver_place_id, day_of_week)
);

