DELETE hour
FROM tb_v2_shop_business_hour hour
JOIN tb_v2_shop shop ON shop.id = hour.shop_id
JOIN tmp_kramen_shop source ON source.naver_place_id = shop.naver_place_id
WHERE shop.deleted_at IS NULL
  AND source.has_hours;

INSERT INTO tb_v2_shop_business_hour (
    shop_id, day_of_week, opens_at, closes_at, break_start, break_end, last_order_at, is_closed
)
SELECT shop.id, source.day_of_week, source.opens_at, source.closes_at, source.break_start, source.break_end, NULL,
    source.is_closed
FROM tmp_kramen_hour source
JOIN tb_v2_shop shop ON shop.naver_place_id = source.naver_place_id
WHERE shop.deleted_at IS NULL;

UPDATE tb_v2_shop shop
JOIN tmp_kramen_shop source ON source.naver_place_id = shop.naver_place_id
SET shop.hours_verified_at = CASE WHEN source.has_hours THEN '2026-09-24 15:00:00' ELSE shop.hours_verified_at END,
    shop.closed_days_text = CASE WHEN source.has_hours THEN source.closed_note ELSE shop.closed_days_text END,
    shop.business_status = CASE
        WHEN source.is_closed THEN 'CLOSED'
        WHEN shop.business_status = 'UNKNOWN' THEN 'OPERATIONAL'
        ELSE shop.business_status
    END,
    shop.ramen_types = CASE
        WHEN JSON_LENGTH(shop.ramen_types) = 0 THEN source.ramen_types
        ELSE shop.ramen_types
    END,
    shop.is_published = CASE WHEN source.is_closed THEN FALSE ELSE shop.is_published END,
    shop.updated_at = CURRENT_TIMESTAMP(6)
WHERE shop.deleted_at IS NULL;

-- 가격은 최저·최고가 서로의 조건이 되므로 따로 바꾼다. 한 SET 안에서는 앞 대입이 뒤 조건에 보일 수 있다.
UPDATE tb_v2_shop shop
JOIN tmp_kramen_shop source ON source.naver_place_id = shop.naver_place_id
SET shop.price_min = source.price_min,
    shop.price_max = source.price_max
WHERE shop.deleted_at IS NULL
  AND shop.price_min IS NULL
  AND shop.price_max IS NULL
  AND source.price_min IS NOT NULL;

DROP TEMPORARY TABLE tmp_kramen_hour;
DROP TEMPORARY TABLE tmp_kramen_shop;
